@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_9f66b99b31ce4de5addf54aff282bf1d.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Nav

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="text-muted mb-2"><small>Refreshing…</small></div>
    }

    <div class="mb-3">
        <label class="form-label me-2">Sort by:</label>
        <a href="@GetSortUrl("newest")" class="btn btn-sm @(_sort == "newest" ? "btn-primary" : "btn-outline-primary") me-1">Newest</a>
        <a href="@GetSortUrl("popular")" class="btn btn-sm @(_sort == "popular" ? "btn-primary" : "btn-outline-primary")">Popular</a>
    </div>

    @if (DisplayedRecipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Title</th>
                    <th>Description</th>
                    <th>Prep Time (min)</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var recipe in DisplayedRecipes)
                {
                    <tr>
                        <td>@recipe.Title</td>
                        <td>@recipe.Description</td>
                        <td>@recipe.PrepTimeMinutes</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _errorMessage;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private string _sort = "newest";

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    private List<Recipe> DisplayedRecipes => _sort == "popular"
        ? _recipes!.OrderByDescending(r => r.PrepTimeMinutes).ToList()
        : _recipes!.OrderByDescending(r => r.Id).ToList();

    protected override async Task OnParametersSetAsync()
    {
        _sort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? "popular"
            : "newest";

        if (CuisineId != _loadedCuisineId)
        {
            await LoadRecipesAsync();
        }
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }
        _loadCts = new CancellationTokenSource();

        using var linked = CancellationTokenSource.CreateLinkedTokenSource(
            _loadCts.Token, _disposeCts.Token);

        _isRefreshing = _recipes is not null;
        _errorMessage = null;
        _loadedCuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, linked.Token);
            _recipes = result;
            _isRefreshing = false;
        }
        catch (OperationCanceledException)
        {
            // Load was superseded or component disposed — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
            _isRefreshing = false;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong loading recipes. Please try again.";
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        _errorMessage = null;
        await LoadRecipesAsync();
    }

    private string GetSortUrl(string sort) =>
        Nav.GetUriWithQueryParameter("sort", sort);

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

